import{_ as t,C as a,o as i,c as r,ag as s,E as n}from"./chunks/framework.yGqRar0R.js";const k=JSON.parse('{"title":"Installing Protocube","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installing-protocube.md","filePath":"guide/installing-protocube.md"}'),l={name:"guide/installing-protocube.md"};function c(p,e,h,d,u,g){const o=a("ComposeDownloads");return i(),r("div",null,[e[0]||(e[0]=s('<h1 id="installing-protocube" tabindex="-1">Installing Protocube <a class="header-anchor" href="#installing-protocube" aria-label="Permalink to &quot;Installing Protocube&quot;">​</a></h1><p><strong>Protocube</strong> is the SLS control plane: it tracks instances and coordinates <strong>nodes</strong> (daemons). Install it once before you add nodes. For shared prerequisites (Linux, WSL, Docker), read <a href="./getting-started.html">Getting started</a> first.</p><p>Official image: <code>ghcr.io/jessefaler/sls/protocube:latest</code><br> Binaries and release notes: <a href="https://github.com/jessefaler/SLS/releases" target="_blank" rel="noreferrer">SLS GitHub Releases</a>.</p><h2 id="docker-compose-file" tabindex="-1">Docker Compose file <a class="header-anchor" href="#docker-compose-file" aria-label="Permalink to &quot;Docker Compose file&quot;">​</a></h2><p>Download the official compose definition or open it on GitHub: <a href="https://github.com/jessefaler/SLS/blob/main/protocube/docker-compose.yml" target="_blank" rel="noreferrer"><code>protocube/docker-compose.yml</code></a>.</p>',5)),n(o,{which:"protocube"}),e[1]||(e[1]=s(`<h2 id="run-protocube-with-docker-recommended" tabindex="-1">Run Protocube with Docker (recommended) <a class="header-anchor" href="#run-protocube-with-docker-recommended" aria-label="Permalink to &quot;Run Protocube with Docker (recommended)&quot;">​</a></h2><ol><li><p>Save the compose file as <code>docker-compose.yml</code> in an empty directory (use the download above, or copy from GitHub).</p></li><li><p>Create the host paths the file bind-mounts (adjust ownership to the user that runs Docker if you do not run as root):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sls/protocube</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/sls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/sls/protocube</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/sls/protocube</span></span></code></pre></div></li><li><p>Start the stack:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div></li></ol><p>The stack maps <strong><code>5620</code></strong> → Protocube. The compose file sets <code>extra_hosts</code> so names like <code>protocube.sls.net</code> and <code>daemon.sls.net</code> resolve <strong>inside</strong> containers; your <strong>host</strong> may still need matching entries in <code>/etc/hosts</code> if you use those hostnames from the host or from native binaries.</p><p>On first start, Protocube should materialize a default config under <strong><code>/etc/sls/protocube/</code></strong> on the host (via the volume mount). Continue with <a href="#configuring-protocube">Configuring Protocube</a>.</p><h2 id="run-protocube-from-a-release-binary" tabindex="-1">Run Protocube from a release binary <a class="header-anchor" href="#run-protocube-from-a-release-binary" aria-label="Permalink to &quot;Run Protocube from a release binary&quot;">​</a></h2><ol><li><p>Open <a href="https://github.com/jessefaler/SLS/releases" target="_blank" rel="noreferrer">SLS Releases</a> and download the <strong>protocube</strong> asset for your OS and CPU architecture.</p></li><li><p>Install it on your <code>PATH</code> or run it from a fixed location:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protocube</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sls/protocube</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/sls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/sls/protocube</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/sls/protocube</span></span></code></pre></div></li><li><p>Start Protocube (optional explicit config path):</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-cCFjc" id="tab-lwPxt-f" checked><label data-title="First run" for="tab-lwPxt-f">First run</label><input type="radio" name="group-cCFjc" id="tab-iLij36d"><label data-title="Custom config" for="tab-iLij36d">Custom config</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./protocube</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./protocube</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sls/protocube/config.yml</span></span></code></pre></div></div></div></li></ol><p>If no config exists yet, the process typically writes defaults under <strong><code>/etc/sls/protocube/</code></strong> — confirm on your version; otherwise create <code>config.yml</code> from the project’s examples.</p><p>Useful commands: <a href="/sls-docs/reference/cli.html#version"><code>protocube version</code></a>, <a href="/sls-docs/reference/cli.html#create-api-key"><code>create-api-key</code></a>, and the rest of the <a href="/sls-docs/reference/cli.html">CLI</a>.</p><h2 id="configuring-protocube" tabindex="-1">Configuring Protocube <a class="header-anchor" href="#configuring-protocube" aria-label="Permalink to &quot;Configuring Protocube&quot;">​</a></h2><p>Protocube reads <strong><code>/etc/sls/protocube/config.yml</code></strong> by default (or the path you pass with <code>--config</code>). There you set blueprint and software roots, API listen address, TLS, and related options. See <a href="/sls-docs/reference/configuration.html">Configuration</a> as that reference page grows.</p><p>When Protocube is running, continue with <a href="./installing-daemon.html">Installing the daemon</a> on each host that should run game servers.</p>`,11))])}const m=t(l,[["render",c]]);export{k as __pageData,m as default};
